{"script": "python3 << 'EOF'
import FreeCAD
import Part

# Try importing FreeCADGui for full functionality
try:
    import FreeCADGui
    has_gui = True
    print("FreeCADGui imported successfully")
except ImportError as e:
    has_gui = False
    print(f"FreeCADGui not available: {e}")

# Create a new document
doc = FreeCAD.newDocument("TorusDocument")

# Create a torus with major radius 5 mm and minor radius 2 mm
torus = Part.makeTorus(5, 2)

# Create a shape object in the document
shape_obj = doc.addObject("Part::Feature", "Torus")
shape_obj.Shape = torus

# Recompute
doc.recompute()

# Check the object's properties
print(f"\nObject properties:")
for prop in shape_obj.PropertiesList:
    print(f"  {prop}: {type(getattr(shape_obj, prop)).__name__}")

# Try setting Material property on the object itself
if hasattr(shape_obj, 'Material'):
    print("\nShape object has Material property")
    try:
        shape_obj.Material = {'Name': 'Wood'}
        print("Set Material to Wood")
    except Exception as e:
        print(f"Could not set Material: {e}")

# If we have GUI, try ViewObject
if has_gui:
    view_obj = doc.getObject("Torus").ViewObject
    if view_obj:
        print("\nViewObject available")
        for prop in view_obj.PropertiesList:
            if 'material' in prop.lower() or 'Material' in prop or 'appearance' in prop.lower() or 'Appearance' in prop:
                print(f"  {prop}")

        # Try to set material
        if hasattr(view_obj, 'Material'):
            try:
                view_obj.Material = {'Name': 'Wood'}
                print("Set ViewObject Material to Wood")
            except Exception as e:
                print(f"Could not set ViewObject Material: {e}")

        if hasattr(view_obj, 'ShapeAppearance'):
            try:
                view_obj.ShapeAppearance = {'Name': 'Wood'}
                print("Set ViewObject ShapeAppearance to Wood")
            except Exception as e:
                print(f"Could not set ViewObject ShapeAppearance: {e}")

# Save
doc.saveAs("/home/user/Unnamed.FCStd")
print("\nDocument saved!")

FreeCAD.closeDocument(doc.Name)
EOF"}

